import {Form} from 'alinea'

export const FormEntry = Form.type('Form', {
  inputs: Form.defaults
})

import {Config} from 'alinea'
import {createCMS} from 'alinea/next'
import * as schema from './schema'

export const cms = createCMS({
  schema,
  workspaces: {
    main: Config.workspace('My site', {
      source: 'content',
      mediaDir: 'public/media',
      roots: {
        pages: Config.root('Pages', {contains: ['Page']}),
        forms: Config.root('Forms', {contains: ['FormEntry']}),
        media: Config.media()
      }
    })
  },
  handlerUrl: '/api/cms'
})

import {Config, Field, Form} from 'alinea'

export const Event = Config.type('Event', {
  fields: {
    title: Field.text('Title'),
    path: Field.path('Path'),
    signUp: Field.form('Sign-up form', {inputs: Form.defaults})
  }
})

import {cms} from '@/cms'
import {FormEntry} from '@/schema/FormEntry'
import {Query} from 'alinea'
import {Form} from 'alinea/ui'
import {notFound} from 'next/navigation'
import {prepareUpload, submitForm} from './actions'

interface PageProps {
  params: Promise<{slug: string}>
}

export default async function FormPage({params}: PageProps) {
  const {slug} = await params
  const form = await cms.first({
    type: FormEntry,
    path: slug,
    select: {id: Query.id, title: Query.title, inputs: FormEntry.inputs}
  })
  if (!form) notFound()
  return (
    <main>
      <h1>{form.title}</h1>
      <Form
        definition={form.inputs}
        action={submitForm.bind(null, form.id)}
        upload={prepareUpload.bind(null, form.id)}
      />
    </main>
  )
}

'use server'

import {cms} from '@/cms'
import type {FormUploadFile} from 'alinea/form'

/** Sends the answers of a visitor to the form in an entry */
export async function submitForm(entryId: string, data: FormData) {
  return cms.forms.submit(entryId, data)
}

/** A ticket for the browser of the visitor to upload a file with */
export async function prepareUpload(entryId: string, file: FormUploadFile) {
  return cms.forms.prepareUpload(entryId, file)
}
